package com.receiptledger.v1.validation;

import com.receiptledger.v1.document.*;import com.receiptledger.v1.item.*;import com.receiptledger.v1.layout.*;import com.receiptledger.v1.ocr.*;import com.receiptledger.v1.structure.*;import org.junit.Test;import java.util.*;import static org.junit.Assert.*;

public class ReceiptValidatorTest {
    @Test public void passesExactReceiptWithNegativeDiscount(){Pipeline p=pipeline(new String[][]{{"우유","3,200"},{"라면","4,990"},{"쿠폰할인","-500"},{"합계","7,690"}});ReceiptValidation v=new ReceiptValidator().validate(p.structure,p.items);assertEquals(ValidationStatus.PASS,v.status);assertEquals(Long.valueOf(8190),v.itemLineSum);assertEquals(Long.valueOf(-500),v.discountSum);assertEquals(Long.valueOf(7690),v.computedNet);assertEquals(Long.valueOf(0),v.difference);}
    @Test public void positiveDiscountRowStillReducesNet(){Pipeline p=pipeline(new String[][]{{"우유","3,200"},{"쿠폰할인","500"},{"합계","2,700"}});ReceiptValidation v=new ReceiptValidator().validate(p.structure,p.items);assertEquals(ValidationStatus.PASS,v.status);assertEquals(Long.valueOf(-500),v.discountSum);}
    @Test public void mismatchIsReportedNotRepaired(){Pipeline p=pipeline(new String[][]{{"우유","3,200"},{"합계","3,100"}});ReceiptValidation v=new ReceiptValidator().validate(p.structure,p.items);assertEquals(ValidationStatus.MISMATCH,v.status);assertEquals(Long.valueOf(100),v.difference);assertTrue(v.issues.contains("RECEIPT_TOTAL_MISMATCH"));}
    @Test public void partialTupleCanPassReceiptTotalWithWarning(){Pipeline p=pipeline(new String[][]{{"과자","2,000","3","5,000"},{"합계","5,000"}});ReceiptValidation v=new ReceiptValidator().validate(p.structure,p.items);assertEquals(ValidationStatus.PASS_WITH_WARNINGS,v.status);assertTrue(v.issues.contains("PARTIAL_ITEM_TUPLE"));}
    @Test public void missingPrintedTotalIsIncomplete(){Pipeline p=pipeline(new String[][]{{"우유","3,200"}});ReceiptValidation v=new ReceiptValidator().validate(p.structure,p.items);assertEquals(ValidationStatus.INCOMPLETE,v.status);assertTrue(v.issues.contains("PRINTED_TOTAL_MISSING"));}
    private static Pipeline pipeline(String[][] rows){List<OcrElement> all=new ArrayList<>();double y=10;for(String[] row:rows){double x=10;for(String s:row){double w=Math.max(12,s.length()*7);Quad q=new Quad(new PointD(x,y),new PointD(x+w,y),new PointD(x+w,y+10),new PointD(x,y+10));all.add(new OcrElement(s,q,q));x+=w+22;}y+=22;}Collections.reverse(all);OcrLine line=new OcrLine("wrong",null,null,all);OcrDocument doc=new OcrDocument("raw",240,(int)y,Collections.singletonList(new OcrBlock("b",null,null,Collections.singletonList(line))));ReceiptLayout layout=new ReceiptLayoutAnalyzer().analyze(doc);ReceiptStructure structure=new ReceiptStructureAnalyzer().analyze(layout);ItemTupleResult items=new ItemTupleSolver().solve(structure);return new Pipeline(structure,items);}
    private static final class Pipeline{final ReceiptStructure structure;final ItemTupleResult items;Pipeline(ReceiptStructure s,ItemTupleResult i){structure=s;items=i;}}
}
